#!/bin/bash
# Hotpatch: chat UI, quiz T/F+nav, guest access revoke
set -e

echo "Patching page.tsx..."
mkdir -p "$(dirname '/home/axisai/axis-frontend/app/(dashboard)/learn/[spaceId]/content/[contentId]/page.tsx')"
cp "/home/axisai/axis-frontend/app/(dashboard)/learn/[spaceId]/content/[contentId]/page.tsx" "/home/axisai/axis-frontend/app/(dashboard)/learn/[spaceId]/content/[contentId]/page.tsx.bak.$(date +%s)" 2>/dev/null || true
echo "" | base64 -d > "/home/axisai/axis-frontend/app/(dashboard)/learn/[spaceId]/content/[contentId]/page.tsx"

echo "Patching study-quiz.tsx..."
mkdir -p "$(dirname '/home/axisai/axis-frontend/components/study/study-quiz.tsx')"
cp "/home/axisai/axis-frontend/components/study/study-quiz.tsx" "/home/axisai/axis-frontend/components/study/study-quiz.tsx.bak.$(date +%s)" 2>/dev/null || true
echo "" | base64 -d > "/home/axisai/axis-frontend/components/study/study-quiz.tsx"

echo "Patching share-modal.tsx..."
mkdir -p "$(dirname '/home/axisai/axis-frontend/components/spaces/share-modal.tsx')"
cp "/home/axisai/axis-frontend/components/spaces/share-modal.tsx" "/home/axisai/axis-frontend/components/spaces/share-modal.tsx.bak.$(date +%s)" 2>/dev/null || true
echo "" | base64 -d > "/home/axisai/axis-frontend/components/spaces/share-modal.tsx"

echo "Patching page.tsx..."
mkdir -p "$(dirname '/home/axisai/axis-frontend/app/(dashboard)/spaces/[id]/page.tsx')"
cp "/home/axisai/axis-frontend/app/(dashboard)/spaces/[id]/page.tsx" "/home/axisai/axis-frontend/app/(dashboard)/spaces/[id]/page.tsx.bak.$(date +%s)" 2>/dev/null || true
echo "" | base64 -d > "/home/axisai/axis-frontend/app/(dashboard)/spaces/[id]/page.tsx"

echo "Rebuilding Next.js..."
cd /home/axisai/axis-frontend
npm run build 2>&1 | tail -20
pm2 reload axis-frontend
echo "=== Done ==="